<?php

namespace App\Http\Requests\Rooms;

use App\Gameplay\Engine\Action;
use Illuminate\Foundation\Http\FormRequest;

class SubmitActionRequest extends FormRequest
{
    /**
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        return [
            // Generated by the client per attempt; a retry with the same id is applied only once.
            'client_action_id' => ['required', 'uuid'],
            // The version the client saw; a different current version means its view is outdated.
            'expected_version' => ['required', 'integer', 'min:0'],
            'action' => ['required', 'array'],
            'action.type' => ['required', 'string', 'max:40'],
        ];
    }

    public function action(): Action
    {
        // The whole action object: its game-specific fields are validated by the engine, and
        // validated() would only keep the keys that have rules here ("type").
        /** @var array<string, mixed> $data */
        $data = $this->input('action');

        return Action::fromArray($data);
    }
}
